155	/** Looks like std::thread but allocates threads in GlobalThreadPool.
156	  * Also holds ThreadStatus for ClickHouse.
157	  */
158	class ThreadFromGlobalPool : boost::noncopyable
159	{
160	public:
161	    ThreadFromGlobalPool() = default;
162	
163	    template <typename Function, typename... Args>
164	    explicit ThreadFromGlobalPool(Function && func, Args &&... args)
165	        : state(std::make_shared<State>())
166	    {
167	        /// NOTE:
168	        /// - If this will throw an exception, the destructor won't be called
169	        /// - this pointer cannot be passed in the lambda, since after detach() it will not be valid
170	        GlobalThreadPool::instance().scheduleOrThrow([
171	            state = state,
172	            func = std::forward<Function>(func),
173	            args = std::make_tuple(std::forward<Args>(args)...)]() mutable /// mutable is needed to destroy capture
174	        {
175	            SCOPE_EXIT(state->event.set());
176	
177	            state->thread_id = std::this_thread::get_id();
178	
179	            /// This moves are needed to destroy function and arguments before exit.
180	            /// It will guarantee that after ThreadFromGlobalPool::join all captured params are destroyed.
181	            auto function = std::move(func);
182	            auto arguments = std::move(args);
183	
184	            /// Thread status holds raw pointer on query context, thus it always must be destroyed
185	            /// before sending signal that permits to join this thread.
186	            DB::ThreadStatus thread_status;
187	            std::apply(function, arguments);
188	        });
189	    }
190	
191	    ThreadFromGlobalPool(ThreadFromGlobalPool && rhs) noexcept
192	    {
193	        *this = std::move(rhs);
194	    }
195	
196	    ThreadFromGlobalPool & operator=(ThreadFromGlobalPool && rhs) noexcept
197	    {
198	        if (initialized())
199	            abort();
200	        state = std::move(rhs.state);
201	        return *this;
202	    }
203	
204	    ~ThreadFromGlobalPool()
205	    {
206	        if (initialized())
207	            abort();
208	    }
209	
210	    void join()
211	    {
212	        if (!initialized())
213	            abort();
214	
215	        state->event.wait();
216	        state.reset();
217	    }
218	
219	    void detach()
220	    {
221	        if (!initialized())
222	            abort();
223	        state.reset();
224	    }
225	
226	    bool joinable() const
227	    {
228	        if (!state)
229	            return false;
230	        /// Thread cannot join itself.
231	        if (state->thread_id == std::this_thread::get_id())
232	            return false;
233	        return true;
234	    }
235	
236	private:
237	    struct State
238	    {
239	        /// Should be atomic() because of possible concurrent access between
240	        /// assignment and joinable() check.
241	        std::atomic<std::thread::id> thread_id;
242	
243	        /// The state used in this object and inside the thread job.
244	        Poco::Event event;
245	    };
246	    std::shared_ptr<State> state;
247	
248	    /// Internally initialized() should be used over joinable(),
249	    /// since it is enough to know that the thread is initialized,
250	    /// and ignore that fact that thread cannot join itself.
251	    bool initialized() const
252	    {
253	        return static_cast<bool>(state);
254	    }

